// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address creator, address debtToken) public {
        vm.assume(creator != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(creator != debtToken);

        vm.prank(creator);
        address cooler = factory.generateCooler(ERC20(debtToken), ERC20(debtToken));

        assertTrue(factory.created(cooler));
        C cloned = C(cooler);

        // General rule: the cooler's owner is the address that generated it,
        // which is distinct from the debt token, so owner() != debt().
        assertTrue(cloned.owner() != cloned.debt());
    }
}

