pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function testFuzz_property(address a, address b) public {
        // Admissible domain: embedded immutable-arg addresses are non-zero and distinct.
        vm.assume(a != address(0));
        vm.assume(b != address(0));
        vm.assume(a != b);

        // Build a payload with a at immutable-arg offset 0x0 and b at offset 0x20,
        // followed by the 2-byte payload length that the Clone layout requires.
        bytes memory payload = abi.encodePacked(
            bytes32(uint256(uint160(a))),
            bytes32(uint256(uint160(b))),
            uint16(64)
        );

        // owner() is a pure function reading immutable args from the call's own calldata;
        // route the probe through the helper so we control the tail calldata.
        address got = caller.probeOwner(address(c), payload);

        // General rule: for ANY tail calldata whose 0x0 immutable arg is a,
        // owner() returns exactly a. The mutant reads offset 0x28 instead,
        // so it returns a different address for admissible (a, b).
        assertTrue(got == a);
    }
}

contract Caller {
    function probeOwner(address target, bytes memory payload) external returns (address) {
        bytes memory data = abi.encodePacked(
            C.owner.selector,
            payload
        );
        (bool ok, bytes memory ret) = target.call(data);
        require(ok, "probe failed");
        return abi.decode(ret, (address));
    }
}

