pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address ownerAddr, address factoryAddr) public {
        vm.assume(ownerAddr != factoryAddr);

        // Mimic a clone call: selector(4) + 4 immutable-arg words + 2-byte length.
        // Reference: owner() reads arg at offset 0x0 (bytes 4..35, shr 0x60 -> top 20 bytes of word0).
        // Mutant:    owner() reads arg at offset 0x3c (bytes 64..95, top 20 bytes of word3).
        bytes memory cd = abi.encodePacked(
            C.owner.selector,
            bytes32(uint256(uint160(ownerAddr))),   // arg @ 0x00: owner
            bytes32(uint256(uint160(0x1111))),      // arg @ 0x14: collateral (padding)
            bytes32(uint256(uint160(0x2222))),      // arg @ 0x28: debt (padding)
            bytes32(uint256(uint160(factoryAddr))), // arg @ 0x3c: factory
            bytes2(uint16(92))                      // immutable args length
        );

        (bool ok, bytes memory ret) = address(c).call(cd);
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (address)) == ownerAddr);
    }
}

