pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address ownerArg, address otherArg) public {
        // Domain: distinct, nonzero addresses so the two immutable-arg slots provably differ.
        vm.assume(ownerArg != address(0));
        vm.assume(otherArg != address(0));
        vm.assume(ownerArg != otherArg);

        // Mimic the factory-created clone calldata layout:
        // appended data = owner(20) | collateral(20) | debt(20) | factory(20) | length trailer (2 bytes = 82).
        // The other three slots are filled with otherArg so only offset 0x0 holds ownerArg.
        bytes memory payload = abi.encodePacked(
            C.owner.selector,
            bytes20(ownerArg),
            bytes20(otherArg),
            bytes20(otherArg),
            bytes20(otherArg),
            uint16(82)
        );

        (bool ok, bytes memory ret) = address(c).call(payload);
        assertTrue(ok && abi.decode(abi.encodePacked(hex"000000000000000000000000", bytes20(ret[24:44])), (address)) == ownerArg);
    }
}

