pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // Admissible domain: any actor address, including all-zero-adjacent values;
        // keep the domain wide so the fuzzer explores the full space.
        vm.assume(actor != address(0xdead));

        // General rule: c.owner() reads the owner immutable argument (offset 0x0),
        // which is always a meaningful, non-zero address in the clone's calldata;
        // it must therefore never be address(0), regardless of any fuzzed input.
        // The buggy version reads offset 0x3c instead, which resolves past the
        // executing call's calldata and yields address(0) for every input.
        assertTrue(c.owner() != address(0), "owner() must return the non-zero owner arg at offset 0x0");
    }
}

