pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 x) public {
        // Drive the boundary through the public pure getter; x keeps the fuzz domain wide.
        address gotCollateral;
        bool ok = true;
        try c.collateral() returns (ERC20 got) {
            gotCollateral = address(got);
        } catch {
            ok = false;
        }
        // General rule: on any admissible call, collateral() (reading immutable arg at 0x14,
        // which is empty calldata -> address(0)) must differ from owner() (reading arg 0x0,
        // a nonzero selector-derived address). The mutant makes collateral() read 0x0 like
        // owner(), so both return the same address and the rule breaks.
        assertTrue(ok && gotCollateral != c.owner());
    }
}

