pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address coll, address debt, address actor) public {
        // The rule is only meaningful for two distinct tokens; keep the domain wide otherwise.
        vm.assume(coll != debt);
        vm.assume(actor != address(0));

        // Drive the factory to create a cooler clone with the fuzzed immutable args.
        vm.prank(actor);
        address cooler = factory.generateCooler(ERC20(coll), ERC20(debt));

        // General rule: the clone's collateral() always reports the collateral token
        // passed at creation (and hence differs from its debt token).
        C coolerC = C(cooler);
        assertTrue(
            coolerC.collateral() == ERC20(coll) && coolerC.collateral() != coolerC.debt(),
            "collateral() must return the collateral immutable arg"
        );
    }
}
